<div class="tc-cs__grid tc-cs__grid--notify"><div><article class="tc-cs__card"><h2><i class="bi bi-sliders"></i> Canales de notificación</h2><p class="tc-cs__hint">No existe catálogo persistente de canales en el esquema actual.</p><div class="tc-cs__empty"><i class="bi bi-bell"></i><p>No hay canales configurados en MariaDB.</p></div></article><article class="tc-cs__card tc-cs__section"><h2><i class="bi bi-lightning"></i> Reglas de alerta</h2><div class="tc-cs__table-wrap"><table><thead><tr><th>Regla</th><th>Condición / Disparador</th><th>Canales</th><th>Acción</th></tr></thead><tbody><tr><td colspan="4">No hay reglas de notificación registradas.</td></tr></tbody></table></div></article><article class="tc-cs__card tc-cs__section"><h2><i class="bi bi-list-ul"></i> Eventos de notificaciones recientes</h2><form method="GET" class="tc-cs__toolbar"><label><i class="bi bi-search"></i><input type="search" name="buscar" value="{{ request('buscar') }}" placeholder="Buscar en tus notificaciones…"></label><select name="estado" aria-label="Estado de notificaciones" onchange="this.form.submit()"><option value="todas" @selected(request('estado', 'todas') === 'todas')>Todas</option><option value="no_leidas" @selected(request('estado') === 'no_leidas')>No leídas</option><option value="leidas" @selected(request('estado') === 'leidas')>Leídas</option></select><button type="submit" class="tc-cs__button">Buscar</button></form><div class="tc-cs__table-wrap"><table><thead><tr><th>Tipo</th><th>Contenido</th><th>Estado</th><th>Fecha</th><th>Acción</th></tr></thead><tbody>@forelse ($notificaciones as $notificacion)<tr><td>{{ $notificacion->nombreTipo() }}</td><td>{{ $notificacion->datosLegibles() }}</td><td>{{ $notificacion->leido_en ? 'Leída' : 'No leída' }}</td><td>{{ $notificacion->creado_en }}</td><td>@if (! $notificacion->leido_en)<form method="post" action="{{ route('management.account.notifications.read', $notificacion->getKey()) }}">@csrf @method('PATCH')<button type="submit" class="